#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> grid(N, vector<int>(M));
    for (int i = 0; i < N; i++) {
        string s;
        cin >> s;
        for (int j = 0; j < M; j++) {
            grid[i][j] = s[j] - '0';
        }
    }

    // We consider each row as a bitmask over GF(2) of length M.
    // The condition is: sum over chosen rows (XOR) and chosen columns == 1.
    // Equivalent to: there exists at least one cell (i,j) with 1 where
    // exactly an odd number of selected rows and columns cover it.
    // This happens iff the rows selected are linearly independent in a certain sense.

    // Count rank of row vectors over GF(2)
    vector<int> rows(N);
    for (int i = 0; i < N; i++) {
        int mask = 0;
        for (int j = 0; j < M; j++) {
            if (grid[i][j]) mask |= (1 << j);
        }
        rows[i] = mask;
    }

    int rank = 0;
    vector<int> basis(M, 0);
    for (int i = 0; i < N; i++) {
        int x = rows[i];
        for (int j = M-1; j >= 0; j--) {
            if ((x >> j) & 1) {
                if (basis[j]) {
                    x ^= basis[j];
                } else {
                    basis[j] = x;
                    rank++;
                    break;
                }
            }
        }
    }

    // Number of row subsets that give odd sum for SOME column subset:
    // All row subsets produce an odd sum for exactly half of column subsets
    // if the rows span a nonzero vector. Actually:
    // For each non-zero linear combination of rows, exactly half of column
    // subsets give odd sum. The zero combination gives odd sum for no column subsets.

    int totalRowSubsets = 1;
    for (int i = 0; i < N; i++) totalRowSubsets = totalRowSubsets * 2 % MOD;

    int totalColSubsets = 1;
    for (int j = 0; j < M; j++) totalColSubsets = totalColSubsets * 2 % MOD;

    // Number of row subsets giving non-zero vector = totalRowSubsets - 2^(N - rank)
    int zeroCombos = 1;
    for (int i = 0; i < N - rank; i++) zeroCombos = zeroCombos * 2 % MOD;

    int nonZeroCombos = (totalRowSubsets - zeroCombos + MOD) % MOD;

    // For each non-zero combination, exactly half of column subsets yield odd sum
    int ans = (int64)nonZeroCombos * ((int64)totalColSubsets * (MOD+1)/2 % MOD) % MOD;

    cout << ans << "\n";

    return 0;
}

