using namespace std;

static const long long MOD = 998244353;

// fast power modulo
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

// Rank over GF(2) for vectors represented by uint64_t blocks
int gf2_rank(vector<vector<unsigned long long>> mat, int rows, int cols) {
    int blocks = (cols + 63) >> 6;
    int rank = 0;
    for (int col = 0; col < cols; ++col) {
        int b = col >> 6;
        unsigned long long mask = 1ULL << (col & 63);
        int pivot = -1;
        for (int i = rank; i < rows; ++i) {
            if (mat[i][b] & mask) {
                pivot = i;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(mat[rank], mat[pivot]);
        for (int i = 0; i < rows; ++i) {
            if (i != rank && (mat[i][b] & mask)) {
                for (int k = 0; k < blocks; ++k) mat[i][k] ^= mat[rank][k];
            }
        }
        ++rank;
        if (rank == rows) break;
    }
    return rank;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<string> s(N);
    for (int i = 0; i < N; ++i) {
        cin >> s[i];
    }

    // Let x in GF(2)^N indicate chosen rows, y in GF(2)^M chosen columns.
    // We need count of pairs (x,y) such that x^T A y = 1.
    //
    // For fixed y, value is x dot (A y).
    // If A y = 0, then no x works.
    // If A y != 0, exactly half of x work: 2^(N-1).
    //
    // Therefore answer = (# of y with A y != 0) * 2^(N-1).
    // Number of y with A y = 0 is size of nullspace = 2^(M-rank),
    // where rank is rank(A) over GF(2).
    // So # of y with A y != 0 = 2^M - 2^(M-rank).
    //
    // Answer = (2^M - 2^(M-rank)) * 2^(N-1), except when N=0 (not possible here).

    int blocks = (M + 63) >> 6;
    vector<vector<unsigned long long>> mat(N, vector<unsigned long long>(blocks, 0));

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            if (s[i][j] == '1') {
                mat[i][j >> 6] |= 1ULL << (j & 63);
            }
        }
    }

    int r = gf2_rank(mat, N, M);

    long long totalY = modpow(2, M);
    long long zeroY = modpow(2, M - r);
    long long nonzeroImageY = (totalY - zeroY + MOD) % MOD;
    long long waysX = modpow(2, N - 1);

    long long ans = nonzeroImageY * waysX % MOD;
    cout << ans << '\n';
    return 0;
}

