int main() {
    scanf("%d %d", &N, &M);
    int words = (M + 63) / 64;
    for (int i = 0; i < N; i++) {
        memset(mat[i], 0, sizeof(ull) * words);
        for (int j = 0; j < M; j++) {
            int v; scanf("%d", &v);
            if (v) mat[i][j/64] |= (1ULL << (j%64));
        }
    }
    // Gaussian elimination over GF(2)
    int rank = 0;
    for (int col = 0; col < M && rank < N; col++) {
        int pivot = -1;
        for (int row = rank; row < N; row++) {
            if ((mat[row][col/64] >> (col%64)) & 1) { pivot = row; break; }
        }
        if (pivot == -1) continue;
        // swap
        ull tmp[WORDS]; memcpy(tmp, mat[rank], sizeof(ull)*words);
        memcpy(mat[rank], mat[pivot], sizeof(ull)*words);
        memcpy(mat[pivot], tmp, sizeof(ull)*words);
        for (int row = 0; row < N; row++) {
            if (row != rank && ((mat[row][col/64] >> (col%64)) & 1)) {
                for (int w = 0; w < words; w++) mat[row][w] ^= mat[rank][w];
            }
        }
        rank++;
    }
    if (N == 0 || M == 0) { printf("0\n"); return 0; }
    long long ans = power(2, N-1, MOD) % MOD * ((power(2, M, MOD) - power(2, M-rank, MOD) + MOD) % MOD) % MOD;
    printf("%lld\n", ans);
    return 0;
}

