#define MOD 998244353LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *mask = (int *)malloc(sizeof(int) * M);
    for (int j = 0; j < M; j++) mask[j] = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int x;
            scanf("%d", &x);
            if (x & 1) mask[j] ^= (1 << i);
        }
    }

    int size = 1 << N;
    long long *cnt = (long long *)calloc(size, sizeof(long long));
    for (int j = 0; j < M; j++) cnt[mask[j]]++;

    /* Walsh-Hadamard transform on cnt */
    for (int bit = 0; bit < N; bit++) {
        for (int s = 0; s < size; s++) {
            if ((s & (1 << bit)) == 0) {
                long long a = cnt[s];
                long long b = cnt[s | (1 << bit)];
                cnt[s] = a + b;
                cnt[s | (1 << bit)] = a - b;
            }
        }
    }

    long long ans = 0;
    long long pow2M = mod_pow(2, M);

    for (int s = 0; s < size; s++) {
        long long ws = cnt[s];                  /* sum_j (-1)^{<s, col_j>} */
        long long evenB = (pow2M + ws) % MOD;   /* 2 * #B with parity 0 */
        long long oddB  = (pow2M - ws) % MOD;   /* 2 * #B with parity 1 */
        if (evenB < 0) evenB += MOD;
        if (oddB < 0) oddB += MOD;

        /* #B with odd parity = oddB / 2 modulo MOD */
        ans += oddB;
        if (ans >= MOD) ans -= MOD;
    }

    /* divide by 2 */
    ans = ans * ((MOD + 1) / 2) % MOD;

    printf("%lld\n", ans);

    free(mask);
    free(cnt);
    return 0;
}

