            for (int i = rank; i < N; i++) {
                if ((rows[i] & (1L << col)) != 0) {
                    pivot = i;
                    break;
                }
            }
            if (pivot == -1) continue;
            // Swap
            long temp = rows[rank];
            rows[rank] = rows[pivot];
            rows[pivot] = temp;
            // Eliminate other rows
