import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        BitSet[] rows = new BitSet[N];
        for (int i = 0; i < N; i++) rows[i] = new BitSet(M);

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int x = fs.nextInt();
                if ((x & 1) == 1) rows[i].set(j);
            }
        }

        int rank = 0;
        for (int col = 0; col < M && rank < N; col++) {
            int pivot = -1;
            for (int i = rank; i < N; i++) {
                if (rows[i].get(col)) {
                    pivot = i;
                    break;
                }
            }
            if (pivot == -1) continue;

            BitSet tmp = rows[rank];
            rows[rank] = rows[pivot];
            rows[pivot] = tmp;

            for (int i = 0; i < N; i++) {
                if (i != rank && rows[i].get(col)) {
                    rows[i].xor(rows[rank]);
                }
            }
            rank++;
        }

        if (rank == 0) {
            System.out.println(0);
            return;
        }

        long ans = modPow(2, N + M - 1);
        System.out.println(ans);
    }
}
